/**
 * `docs/glossary.md`, parsed for the public `/glossary` page (#1289, register row WEB-07).
 *
 * **One register, two renderings.** The document is generated by `scripts/gen-glossary.mjs` from
 * the schema comments in `content/`, and it is the repository's glossary: this module reads it and
 * shapes it for a page, and nothing here holds a definition of its own. That is the whole reason
 * the page does not author a term list — a second copy would drift from the document the generator
 * regenerates and the gate holds current, and the copy on the site is the one a reader would
 * believe.
 *
 * **Pure, so the parse is testable without a tree.** No `node:fs` and no React: the reader is
 * `lib/docs/tree.ts::readDocDocument`, the page passes its text in. `tests/glossary.test.ts` drives
 * the committed document and the malformed shapes a generator change could produce.
 *
 * **The document's own furniture is dropped, not published.** The generated page carries a
 * `docs-nav` region between two HTML comments — a crumb, "prev", "next" — written as links to
 * sibling markdown files. Those addresses are the documentation reader's, so a public page that
 * printed them would offer a visitor four links that 404. The region is removed here, by its
 * markers, and a marker with no end is a named failure rather than a page with half a crumb on it.
 *
 * **A source line is structured, not prose.** Every entry ends with
 * `Source: [content/record.ts](../content/record.ts) — \`zTemplate\`.`, which the page draws as a
 * label plus the file and declaration as code. The link target is the checkout's own relative
 * path, so it is never turned into an anchor: the file is not published, and a link to it would be
 * a link to nothing.
 *
 * **Malformed is a named failure.** `GlossaryUnreadable` carries a sentence the page can draw, in
 * the shape `lib/spec/file.ts::SpecUnreadable` uses. A term with no definition, a definition with
 * no source, two terms that would share an anchor and a document with no terms at all are all
 * failures — "the glossary is empty" and "the glossary could not be read" are different statements
 * and only one of them is ever true.
 */

/** Where a definition came from, as the document names it: `content/record.ts`, `zTemplate`. */
export interface GlossarySource {
  /** The file the prose is the comment of, repo-relative — `content/assessment.ts`. */
  readonly file: string;
  /** The declaration inside that file, when the entry names one (`zOpinionsObject`), else null. */
  readonly declaration: string | null;
}

/** One term: its definition's paragraphs, where they came from, and the id it is anchored on. */
export interface GlossaryTerm {
  readonly term: string;
  /** The `id` the term's section carries — what the term index links to. */
  readonly anchor: string;
  readonly paragraphs: readonly string[];
  readonly sources: readonly GlossarySource[];
}

/** The document, without the furniture a page does not publish. */
export interface GlossaryDocument {
  readonly title: string;
  /** The paragraphs above the first term — the document's own statement of what it is. */
  readonly intro: readonly string[];
  readonly terms: readonly GlossaryTerm[];
}

/** The document could not be read as a glossary. `reason` is the sentence the page prints. */
export class GlossaryUnreadable extends Error {
  readonly reason: string;

  constructor(reason: string) {
    super(`the glossary document could not be read: ${reason}`);
    this.name = "GlossaryUnreadable";
    this.reason = reason;
  }
}

/** The generated page's documentation-navigation region, by its markers (`scripts/docs-nav.mjs`). */
const NAV_BEGIN = "<!-- docs-nav:begin -->";
const NAV_END = "<!-- docs-nav:end -->";

/**
 * The document with its `docs-nav` region removed.
 *
 * Absent markers are tolerated — a document written by hand has no region — but an opening marker
 * with no closing one is a failure: the alternative is publishing the crumb's links, or silently
 * cutting the rest of the file.
 */
function withoutNavRegion(markdown: string): string {
  const start = markdown.indexOf(NAV_BEGIN);
  if (start === -1) return markdown;
  const end = markdown.indexOf(NAV_END, start);
  if (end === -1) {
    throw new GlossaryUnreadable(`${NAV_BEGIN} has no ${NAV_END} after it`);
  }
  return `${markdown.slice(0, start)}${markdown.slice(end + NAV_END.length)}`;
}

/** The anchor a term's section carries: lowercase, punctuation collapsed to single hyphens. */
export function glossaryAnchor(term: string): string {
  const anchor = term
    .toLowerCase()
    .normalize("NFKD")
    .replace(/[^a-z0-9]+/g, "-")
    .replace(/^-+|-+$/g, "");
  if (anchor === "") {
    throw new GlossaryUnreadable(
      `the term "${term}" has no characters an anchor can be built from`,
    );
  }
  return anchor;
}

/** `Source: `, the prefix that turns a paragraph into an attribution rather than a definition. */
const SOURCE_PREFIX = /^Source:\s*/;
/** The markdown link the attribution opens with: `[content/record.ts](../content/record.ts)`. */
const SOURCE_LINK = /\[([^\]]+)\]\(([^)]+)\)/;
/** The declaration it names, in a code span: `` `zTemplate` ``. */
const DECLARATION = /`([^`]+)`/;

/** One attribution line, structured. Throws when the line names no file. */
function sourceOf(paragraph: string, term: string): GlossarySource {
  const link = SOURCE_LINK.exec(paragraph);
  if (link === null) {
    throw new GlossaryUnreadable(`the source line for "${term}" carries no file link`);
  }
  const file = link[1].trim();
  if (file === "" || /^(?:[a-z]+:|\/)/i.test(file)) {
    throw new GlossaryUnreadable(
      `the source line for "${term}" names "${file}", which is not a path in this repository`,
    );
  }
  const declaration = DECLARATION.exec(paragraph.slice(link.index + link[0].length));
  return { file, declaration: declaration === null ? null : declaration[1].trim() };
}

/** One `## ` section: its definitions and its attributions, kept apart. */
function termOf(heading: string, paragraphs: readonly string[]): GlossaryTerm {
  const prose: string[] = [];
  const sources: GlossarySource[] = [];
  for (const paragraph of paragraphs) {
    if (!SOURCE_PREFIX.test(paragraph)) {
      prose.push(paragraph);
      continue;
    }
    sources.push(sourceOf(paragraph, heading));
  }
  if (prose.length === 0) {
    throw new GlossaryUnreadable(`the term "${heading}" defines nothing`);
  }
  if (sources.length === 0) {
    throw new GlossaryUnreadable(`the term "${heading}" names no source file`);
  }
  return { term: heading, anchor: glossaryAnchor(heading), paragraphs: prose, sources };
}

/**
 * The document, parsed. Throws `GlossaryUnreadable` — never a partial document — so the page draws
 * one honest sentence instead of a glossary that quietly lost an entry.
 */
export function parseGlossary(markdown: string): GlossaryDocument {
  const lines = withoutNavRegion(markdown).split("\n");
  const sections: { heading: string | null; paragraphs: string[] }[] = [
    { heading: null, paragraphs: [] },
  ];
  let title: string | null = null;
  let buffer: string[] = [];

  /** Close the paragraph being built, if it has any text. */
  const flush = (): void => {
    const text = buffer.join(" ").replace(/\s+/g, " ").trim();
    if (text !== "") sections[sections.length - 1].paragraphs.push(text);
    buffer = [];
  };

  for (const line of lines) {
    if (line.trim() === "") {
      flush();
      continue;
    }
    const h1 = /^# (.+)$/.exec(line);
    if (h1 !== null) {
      flush();
      if (title !== null) {
        throw new GlossaryUnreadable(`the document carries a second title ("${h1[1].trim()}")`);
      }
      title = h1[1].trim();
      continue;
    }
    const h2 = /^## (.+)$/.exec(line);
    if (h2 !== null) {
      flush();
      sections.push({ heading: h2[1].trim(), paragraphs: [] });
      continue;
    }
    if (/^#{3,6} /.test(line)) {
      throw new GlossaryUnreadable(
        `the document carries a heading this page does not publish ("${line.trim()}")`,
      );
    }
    buffer.push(line.trim());
  }
  flush();

  if (title === null) {
    throw new GlossaryUnreadable("the document opens with no `# ` title");
  }
  const head = sections[0];
  if (head === undefined) {
    throw new GlossaryUnreadable("the document carries no section at all");
  }
  if (head.paragraphs.length === 0) {
    throw new GlossaryUnreadable("the document says nothing before its first term");
  }
  const terms = sections.slice(1).map((section) => {
    if (section.heading === null) {
      throw new GlossaryUnreadable("a paragraph sits outside any term's section");
    }
    return termOf(section.heading, section.paragraphs);
  });
  if (terms.length === 0) {
    throw new GlossaryUnreadable("the document defines no terms");
  }

  const anchors = new Set<string>();
  for (const term of terms) {
    if (anchors.has(term.anchor)) {
      throw new GlossaryUnreadable(`two terms share the anchor "#${term.anchor}"`);
    }
    anchors.add(term.anchor);
  }

  return { title, intro: head.paragraphs, terms };
}
